"""Square law: y = x * x."""

import numpy as np
from gnuradio import gr


class blk(gr.sync_block):
    """Square law: y = x * x."""

    def __init__(self):
        gr.sync_block.__init__(self, name="Square Law", in_sig=[np.float32], out_sig=[np.float32])

    def work(self, input_items, output_items):
        x = input_items[0]
        output_items[0][:] = x * x
        return len(output_items[0])
